import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import http from 'node:http';
import https from 'node:https';
import { syncBuiltinESMExports } from 'node:module';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

if (process.env.JEV_RELEASE_PRELOAD === '1') {
  let requests = 0;
  const forbidden = () => { throw new Error('Release verification forbids real network access.'); };
  http.request = forbidden; http.get = forbidden;
  https.request = forbidden; https.get = forbidden;
  syncBuiltinESMExports();
  process.on('exit', () => {
    if (requests !== Number(process.env.JEV_RELEASE_REQUESTS)) process.exitCode = 91;
  });
  globalThis.fetch = async (url, init) => {
    requests++;
    assert.equal(process.env.JEV_RELEASE_RESPONSE, 'fixture');
    assert.equal(requests, 1);
    assert.equal(String(url), process.env.JEV_RELEASE_ENDPOINT);
    assert.equal(init.redirect, 'error');
    assert.equal(new Headers(init.headers).get('authorization'), 'Bearer release-fixture-key');
    const body = JSON.parse(String(init.body));
    assert.deepEqual(Object.keys(body.questions).sort(),
      ['needsMoreInformation', 'needsTesting', 'nextAction', 'stuck', 'taskComplete'].sort());
    const vercel = process.env.JEV_RELEASE_PROVIDER === 'vercel';
    assert.equal(vercel ? new Headers(init.headers).get('ai-model-id') : body.model,
      process.env.JEV_RELEASE_MODEL);
    const { ACTIONS } = await import(process.env.JEV_RELEASE_TYPES);
    const boolean = (probability) => vercel ? { type: 'boolean', probability } : { type: 'noul', noul: probability };
    const response = {
      model: process.env.JEV_RELEASE_SERVED,
      answers: {
        taskComplete: boolean(0.01), needsMoreInformation: boolean(0.02),
        needsTesting: boolean(0.03), stuck: boolean(0.01),
        nextAction: { type: 'choice', choice: 'SEARCH_REPO',
          probabilities: Object.fromEntries(ACTIONS.map((action) => [action, action === 'SEARCH_REPO' ? 1 : 0])),
          ...(vercel ? {} : { confidence: 0.9 }) },
      },
      ...(vercel ? { providerMetadata: { typesafe: { confidence: { nextAction: 0.9 } } } } : {}),
    };
    return Response.json(process.env.JEV_RELEASE_PROVIDER === 'cloudflare'
      ? { success: true, errors: [], result: response } : response);
  };
} else {
  const directory = path.dirname(fileURLToPath(import.meta.url));
  const repository = path.resolve(process.argv[2]);
  const archive = path.join(directory, 'dev-orchestrator-0.4.0.tgz');
  const consumer = path.join(directory, 'consumer');
  const ownScript = fileURLToPath(import.meta.url);
  if (existsSync(consumer)) {
    assert.ok(!existsSync(path.join(directory, 'verification.json')), 'Verified consumer cannot be reused.');
  } else mkdirSync(consumer);
  writeFileSync(path.join(consumer, 'package.json'), JSON.stringify({
    private: true, name: 'dev-v040-release-consumer', version: '1.0.0',
    type: 'module', scripts: { test: 'node --test' },
  }, null, 2) + '\n');
  writeFileSync(path.join(consumer, 'index.js'), 'export const fixture = true;\n');
  const environment = Object.fromEntries(['PATH', 'HOME', 'TMPDIR', 'LANG', 'XDG_CACHE_HOME']
    .filter((name) => process.env[name] !== undefined).map((name) => [name, process.env[name]]));
  environment.CI = '1';
  const install = spawnSync('pnpm', ['add', '--offline', '--ignore-scripts', '--save-dev', archive],
    { cwd: consumer, env: environment, encoding: 'utf8', timeout: 120000 });
  writeFileSync(path.join(directory, 'install.log'), install.stdout + install.stderr);
  assert.equal(install.status, 0, 'Offline archive install failed; see install.log.');
  const installed = path.join(consumer, 'node_modules/dev-orchestrator');
  const binary = path.join(consumer, 'node_modules/.bin/dev-agent');
  const manifest = JSON.parse(readFileSync(path.join(installed, 'package.json'), 'utf8'));
  assert.equal(manifest.version, '0.4.0');
  assert.deepEqual(Object.keys(manifest.bin), ['dev-agent']);
  assert.equal(existsSync(path.join(consumer, 'node_modules/.bin/jev-agent')), false);
  assert.equal(manifest.name, 'dev-orchestrator');
  assert.equal(manifest.bin['dev-agent'], './dist/cli.js');
  assert.equal(manifest.engines.node, '>=22');
  assert.ok(existsSync(path.join(installed, 'CHANGELOG.md')));
  assert.deepEqual(Object.keys(manifest.dependencies), ['ai']);
  const snapshot = () => {
    const result = {};
    const visit = (directory, prefix = '') => {
      for (const name of readdirSync(directory).sort()) {
        if (!prefix && name === 'node_modules') continue;
        const relative = prefix + name;
        const absolute = path.join(directory, name);
        if (statSync(absolute).isDirectory()) visit(absolute, relative + '/');
        else result[relative] = createHash('sha256').update(readFileSync(absolute)).digest('hex');
      }
    };
    visit(consumer); return result;
  };
  const baseline = snapshot();
  const results = [];
  const account = 'a'.repeat(32);
  const routes = [
    { id: 'typesafe', provider: 'typesafe', model: 'jev-latest', credential: 'TYPESAFE_API_KEY',
      served: 'jev-1.13.0', endpoint: 'https://api.typesafe.ai/v1/systemone' },
    { id: 'vercel', provider: 'vercel', model: 'typesafe-ai/jev', credential: 'AI_GATEWAY_API_KEY',
      served: 'unverified-fixture', endpoint: 'https://ai-gateway.vercel.sh/v4/ai/evaluation-model' },
    { id: 'openrouter-jev', provider: 'openrouter', model: 'typesafe/jev-1.13', credential: 'OPENROUTER_API_KEY',
      served: 'typesafe/jev-release-fixture', endpoint: 'https://openrouter.ai/api/alpha/decisions' },
    { id: 'openrouter-openai', provider: 'openrouter', model: 'openai/gpt-6-luna-decisions', credential: 'OPENROUTER_API_KEY',
      served: 'openai/gpt-6-luna-decisions-release-fixture', endpoint: 'https://openrouter.ai/api/alpha/decisions' },
    ...['clef', 'clef-flash'].map((model) => ({ id: 'cloudflare-' + model, provider: 'cloudflare', model,
      credential: 'CLOUDFLARE_AUTH_TOKEN', served: model,
      endpoint: 'https://api.cloudflare.com/client/v4/accounts/' + account + '/ai/run/@cf/cloudflare/' + model })),
  ];
  const routeEnvironment = (route, legacy = false) => ({
    [legacy ? 'JEV_PROVIDER' : 'ROUTER_PROVIDER']: route.provider, ROUTER_MODEL: route.model,
    [route.credential]: 'release-fixture-key',
    ...(route.provider === 'cloudflare' ? { CLOUDFLARE_ACCOUNT_ID: account } : {}),
  });
  function run(id, args, overrides = {}, expected = {}) {
    const route = expected.route;
    const result = spawnSync(binary, args, { cwd: consumer,
      env: { ...environment, NODE_OPTIONS: '--import=' + ownScript, JEV_RELEASE_PRELOAD: '1',
        JEV_RELEASE_REQUESTS: route ? '1' : '0',
        ...(route ? { JEV_RELEASE_RESPONSE: 'fixture', JEV_RELEASE_PROVIDER: route.provider,
