  assert.equal(existsSync(path.join(consumer, 'node_modules/.bin/jev-agent')), false);
  assert.equal(manifest.name, 'dev-orchestrator');
  assert.equal(manifest.bin['dev-agent'], './dist/cli.js');
  assert.equal(manifest.engines.node, '>=22');
